#!/usr/bin/env python3
"""ATAVIA JC-ENGAGE-1012 - run in Cloud Shell from the live functions folder.
Patches main.py / lib/emails.py / packages json IN PLACE (backups *.pre-engage1012.bak),
compiles, then prints the deploy commands. Idempotent: skips files already patched."""
import io, os, sys, json, py_compile, shutil

EMAILS_BLOCK = '# ============================================================ engagement ==\n# JC-ENGAGE-1012: couples heard nothing between the welcome email and the\n# balance heads-up (and the Lazo plug), and one cancelled a week in citing\n# "no communication". Three warm, non-transactional touches fill the gap:\n#   meet_your_team   2 days after booking  - who we are, what happens next\n#   planning_checkin every 30 days         - while the wedding is > 45 days out\n#   final_week       7 days before         - what we have on file, day-of number\n# All driven by _send_engagement in main.py.\n\n_SIG = (\'<p style="color:#B0713F">&mdash; The Atavia Weddings Team<br>\'\n        \'(336) 537-9590 &middot; info@ataviaweddings.com &middot; ataviaweddings.com</p>\')\n_WRAP = (\'<div style="font-family:Georgia,serif;color:#2B2B2B;max-width:560px;margin:0 auto">\'\n         \'<h1 style="font-weight:normal;letter-spacing:2px">ATAVIA WEDDINGS</h1>{body}\' + _SIG + \'</div>\')\n\n\ndef _first(booking):\n    return booking["client_names"].split("&")[0].strip().split()[0]\n\n\ndef meet_your_team(api_key, booking, q_link=None):\n    first = _first(booking)\n    plan = booking.get("payment_option")\n    bal = ""\n    if plan == "standard" and booking.get("balance_due_date"):\n        bal = (f"<li><b>{booking[\'balance_due_date\']}</b> &mdash; your remaining balance is "\n               f"charged to the card on file, as set out in your agreement. We send a reminder "\n               f"the day before, and you can swap the card any time by replying.</li>")\n    q = ("" if not q_link else\n         f\'<p style="text-align:center;margin:22px 0"><a href="{q_link}" style="background:#B0713F;\'\n         \'color:#FAF7F2;padding:14px 30px;text-decoration:none;letter-spacing:2px;\'\n         \'font-family:Arial,sans-serif;font-size:13px">OPEN YOUR QUESTIONNAIRE</a></p>\')\n    body = f"""\n      <p>Hi {first},</p>\n      <p>Now that the paperwork is done, we wanted to say a proper hello and show you\n      exactly what happens between today and <b>{booking.get(\'event_date\',\'\')}</b>, so\n      there are no surprises and nothing you have to chase.</p>\n      <ul style="line-height:1.7">\n        <li><b>Done:</b> your date is reserved, your agreement is signed, and your\n        <b>{booking.get(\'package_name\',\'\')}</b> coverage is locked in.</li>\n        {bal}\n        <li><b>Whenever you have ten minutes:</b> the Wedding Day Questionnaire (venues,\n        timeline, key people, must-have moments). You can update it any time until two\n        weeks before the wedding.</li>\n        <li><b>Along the way:</b> we check in every few weeks. Reply to any of those with\n        changes, questions, or just to say hi &mdash; a real person reads every one.</li>\n        <li><b>30 days out:</b> we review your questionnaire and build your coverage plan,\n        and reach out if anything needs clarifying.</li>\n        <li><b>The week of:</b> you get your final timeline and the direct number for your\n        filmmaker on the day.</li>\n      </ul>\n      {q}\n      <p>If anything is ever unclear, <b>reply to this email or call (336) 537-9590</b>.\n      You should never have to wonder where things stand.</p>"""\n    return _send(api_key, booking["email"],\n                 f"What happens next — {booking.get(\'event_date\',\'\')}", _WRAP.format(body=body))\n\n\n_CHECKIN_TIPS = [\n    "If your venue has a coordinator, send us their name and number when you have it &mdash; "\n    "it makes the day run smoother for everyone.",\n    "Start a short list of the people who matter most on the day (parents, grandparents, the "\n    "friend who flew in). We make sure they are on film.",\n    "Think about your first look, if you want one. It is the single biggest timeline decision "\n    "and the easiest to change now.",\n    "Sunset is the best light of the day. If you can give us fifteen minutes with the two of "\n    "you around then, those are usually the shots couples love most.",\n    "Readings, vows, toasts: if anyone is writing something personal, a quick heads-up lets us "\n    "capture the audio cleanly.",\n]\n\n\ndef planning_checkin(api_key, booking, q_link, n, days_to_event, q_done):\n    """n-th check-in (0-based) picks a rotating tip."""\n    first = _first(booking)\n    tip = _CHECKIN_TIPS[n % len(_CHECKIN_TIPS)]\n    months = max(1, round(days_to_event / 30))\n    qline = ("Your questionnaire is in &mdash; thank you. Reopen it any time if details change."\n             if q_done else\n             f\'Your questionnaire is still open whenever you are ready: <a href="{q_link}" \'\n             \'style="color:#B0713F">complete it here</a>.\')\n    body = f"""\n      <p>Hi {first},</p>\n      <p>A quick check-in from us &mdash; about <b>{months} month{\'s\' if months != 1 else \'\'}</b>\n      to go until {booking.get(\'event_date\',\'\')}. Nothing is required of you; your date and\n      your coverage are secure.</p>\n      <p>{qline}</p>\n      <p><b>One thing worth thinking about now:</b> {tip}</p>\n      <p>Anything changed &mdash; venue, times, guest count, a new must-have? Just reply and\n      we will update your file the same day.</p>"""\n    return _send(api_key, booking["email"],\n                 f"Checking in — {booking.get(\'event_date\',\'\')}", _WRAP.format(body=body))\n\n\ndef final_week(api_key, booking, q_link, q_done):\n    first = _first(booking)\n    rows = ""\n    for label, key in (("Ceremony", "ceremony_venue"), ("Reception", "reception_venue"),\n                       ("Coverage starts", "start_time"), ("Coverage ends", "end_time")):\n        v = booking.get(key)\n        if v:\n            rows += (f\'<tr><td style="padding:3px 14px 3px 0;color:#6B6B6B;font-size:12px">{label}</td>\'\n                     f\'<td style="padding:3px 0;font-size:13px">{v}</td></tr>\')\n    table = (f\'<table style="width:100%;border-collapse:collapse;margin:16px 0">{rows}</table>\'\n             if rows else "")\n    qline = ("" if q_done else\n             f\'<p><b>We still do not have your questionnaire.</b> Please <a href="{q_link}" \'\n             \'style="color:#B0713F">complete it today</a> so we can plan your coverage properly, \'\n             \'or reply with your timeline and we will take it from there.</p>\')\n    body = f"""\n      <p>Hi {first},</p>\n      <p>One week to go. Here is what we have on file for <b>{booking.get(\'event_date\',\'\')}</b>:</p>\n      {table}\n      {qline}\n      <p>If anything above has changed, reply today. Otherwise you are all set &mdash; we will\n      arrive early, stay out of the way, and capture everything.</p>\n      <p><b>Day-of number:</b> (336) 537-9590. Save it; it reaches us directly on the day.</p>\n      <p>We are so looking forward to it.</p>"""\n    return _send(api_key, booking["email"],\n                 f"One week to go — {booking.get(\'event_date\',\'\')}", _WRAP.format(body=body))\n'
SWEEP_BLOCK = '# ========================================================== engagement ==\n# JC-ENGAGE-1012: see lib/emails.py. Stamps on the booking doc:\n#   meet_sent_at, checkin_count, checkin_last_at, final_week_sent_at\nENGAGE_MEET_AFTER_DAYS = 2        # meet_your_team: days after the retainer is paid\nENGAGE_MEET_MAX_DAYS = 21         # ...but never to a couple who booked longer ago than this\nENGAGE_CHECKIN_EVERY_DAYS = 30    # planning_checkin cadence\nENGAGE_CHECKIN_MIN_DAYS_OUT = 45  # no check-ins inside this window (30-day questionnaire flow takes over)\nENGAGE_FINAL_WEEK_DAYS = 7\nENGAGE_QUIET_AROUND_BALANCE_DAYS = 2   # don\'t stack a check-in on the balance heads-up / charge\n\n\ndef _send_engagement(db, now):\n    """Warm, non-transactional touches between booking and the wedding. One\n    email per booking per run at most; every send is stamped so nothing\n    repeats. Non-fatal throughout."""\n    from google.cloud.firestore_v1.base_query import FieldFilter\n    try:\n        snaps = (db.collection("bookings")\n                   .where(filter=FieldFilter("status", "==", "confirmed")).get())\n    except Exception as e:\n        print(f"engagement query failed: {e}"); return\n    today = now.date()\n    counts = {"meet": 0, "checkin": 0, "final": 0}\n    for snap in snaps:\n        b = snap.to_dict() or {}\n        if b.get("test_mode") or not b.get("email") or "@" not in str(b.get("email")):\n            continue\n        try:\n            ev = datetime.strptime(b.get("event_date_raw", ""), "%Y-%m-%d").date()\n        except ValueError:\n            continue\n        days = (ev - today).days\n        if days < 0:\n            continue\n        paid = b.get("deposit_paid_at") or b.get("created_at")\n        if not paid:\n            continue\n        if hasattr(paid, "tzinfo") and paid.tzinfo is None:\n            paid = paid.replace(tzinfo=timezone.utc)\n        since_paid = (now - paid).days\n        q_done = bool(b.get("questionnaire_submitted_at"))\n        link = _q_link(b["booking_id"], GRATUITY_SECRET.value)\n        bd = b.get("balance_due_at")\n        near_balance = False\n        if bd is not None and not b.get("balance_paid_at"):\n            if hasattr(bd, "tzinfo") and bd.tzinfo is None:\n                bd = bd.replace(tzinfo=timezone.utc)\n            near_balance = abs((bd - now).days) <= ENGAGE_QUIET_AROUND_BALANCE_DAYS\n        try:\n            # 1. final week (highest priority)\n            if days <= ENGAGE_FINAL_WEEK_DAYS and days >= 2 and not b.get("final_week_sent_at"):\n                emails.final_week(RESEND_API_KEY.value, b, link, q_done)\n                snap.reference.update({"final_week_sent_at": firestore.SERVER_TIMESTAMP})\n                counts["final"] += 1\n                continue\n            # 2. meet your team, a couple of days after paying (couples who booked\n            #    before this shipped skip straight to the check-in track)\n            if (not b.get("meet_sent_at") and ENGAGE_MEET_AFTER_DAYS <= since_paid <= ENGAGE_MEET_MAX_DAYS\n                    and days > ENGAGE_FINAL_WEEK_DAYS):\n                bdd = b.get("balance_due_at")\n                b["balance_due_date"] = bdd.strftime("%B %d, %Y") if hasattr(bdd, "strftime") else ""\n                emails.meet_your_team(RESEND_API_KEY.value, b, q_link=link)\n                snap.reference.update({"meet_sent_at": firestore.SERVER_TIMESTAMP})\n                counts["meet"] += 1\n                continue\n            # 3. monthly check-in while the wedding is comfortably far out\n            if ((b.get("meet_sent_at") or since_paid > ENGAGE_MEET_MAX_DAYS)\n                    and days > ENGAGE_CHECKIN_MIN_DAYS_OUT and not near_balance):\n                last = b.get("checkin_last_at") or b.get("meet_sent_at") or paid\n                if hasattr(last, "tzinfo") and last.tzinfo is None:\n                    last = last.replace(tzinfo=timezone.utc)\n                if (now - last).days >= ENGAGE_CHECKIN_EVERY_DAYS:\n                    n = int(b.get("checkin_count") or 0)\n                    emails.planning_checkin(RESEND_API_KEY.value, b, link, n, days, q_done)\n                    snap.reference.update({"checkin_last_at": firestore.SERVER_TIMESTAMP,\n                                           "checkin_count": n + 1})\n                    counts["checkin"] += 1\n        except Exception as e:\n            print(f"engagement failed {b.get(\'booking_id\', snap.id)}: {e}")\n    print(f"engagement: {counts}")\n\n\n'
EDITS = [('    if days_to_event <= 0:\n        raise ValueError("event date must be in the future")\n    second_shooter = bool(data.get("second_shooter"))', '    if days_to_event <= 0:\n        raise ValueError("event date must be in the future")\n    if RULES.get("pif_required_within_days", 0) and days_to_event <= RULES["pif_required_within_days"]:\n        option = "pif"          # JC-ENGAGE-1012: close-in weddings are paid in full at reservation\n    second_shooter = bool(data.get("second_shooter"))'), ('        if event_dt.date() <= datetime.now().date():\n            return _res({"error": "event date must be in the future"}, 400)', '        if event_dt.date() <= datetime.now().date():\n            return _res({"error": "event date must be in the future"}, 400)\n        _dte = (event_dt.date() - datetime.now().date()).days\n        if RULES.get("pif_required_within_days", 0) and _dte <= RULES["pif_required_within_days"]:\n            data["payment_option"] = "pif"   # JC-ENGAGE-1012: close-in weddings are paid in full'), ('LAZO_INVITE_DELAY_DAYS = 3 ', 'LAZO_INVITE_DELAY_DAYS = 7 '), ('    _send_lazo_invites(firestore.client(), datetime.now(timezone.utc))   # JC-LZ-INVITE-0928\n    db = firestore.client()', '    _send_lazo_invites(firestore.client(), datetime.now(timezone.utc))   # JC-LZ-INVITE-0928\n    try:\n        _send_engagement(firestore.client(), datetime.now(timezone.utc))   # JC-ENGAGE-1012\n    except Exception as e:\n        print(f"engagement sweep failed: {e}")\n    db = firestore.client()')]
PKG_CANDIDATES = ['contract/atavia_packages.json', 'atavia_packages.json']
RULE_DAYS = 45

def rd(p): return io.open(p, encoding="utf-8").read()
def wr(p, s):
    shutil.copy(p, p + ".pre-engage1012.bak")
    io.open(p, "w", encoding="utf-8", newline="\n").write(s)

e = rd("lib/emails.py")
if "ENGAGE-1012" in e:
    print("lib/emails.py already patched")
else:
    wr("lib/emails.py", e.rstrip("\n") + "\n\n\n" + EMAILS_BLOCK)
    print("lib/emails.py: appended")

m = rd("main.py")
if "ENGAGE-1012" in m:
    print("main.py already patched")
else:
    lazo = "\n# ======================================================== lazo invite =="
    assert lazo in m, "lazo invite header not found in main.py"
    m = m.replace(lazo, "\n" + SWEEP_BLOCK + lazo.lstrip("\n"), 1)
    for old, new in EDITS:
        assert m.count(old) == 1, "expected exactly one match for: " + old[:70]
        m = m.replace(old, new, 1)
    wr("main.py", m)
    print("main.py: sweep + rule + lazo delay")

for pj in PKG_CANDIDATES:
    if os.path.exists(pj):
        d = json.load(io.open(pj, encoding="utf-8"))
        d["pricing_rules"]["pif_required_within_days"] = RULE_DAYS
        wr(pj, json.dumps(d, indent=2, ensure_ascii=False) + "\n")
        print(pj, ": pif_required_within_days =", RULE_DAYS)
        break
else:
    sys.exit("packages json not found: " + str(PKG_CANDIDATES))

for f in ("main.py", "lib/emails.py"):
    py_compile.compile(f, doraise=True)
print("COMPILED OK - now run the deploy line from the -command.txt file")
